-- Emoji picker: type ":fire" or "emoji: fire" to search by name or keyword.
-- Enter copies the emoji and keeps Zenkai open; Ctrl+K offers the name and codepoints.

local MAX_RESULTS = 50
local find, sub, lower, upper = string.find, string.sub, string.lower, string.upper

local shown = {} -- result id -> emoji index

local function query_term(query)
    local q = lower(query)
    if sub(q, 1, 6) == "emoji:" then return sub(query, 7) end
    if sub(q, 1, 1) == ":" then return sub(query, 2) end
    return nil
end

local function words_of(term)
    local words = {}
    for w in lower(term):gmatch("%S+") do words[#words + 1] = w end
    return words
end

local function title_case(name)
    return upper(sub(name, 1, 1)) .. sub(name, 2)
end

local function codepoints(ch)
    local parts = {}
    for _, c in utf8.codes(ch) do parts[#parts + 1] = string.format("U+%04X", c) end
    return table.concat(parts, " ")
end

local function add(i)
    -- glyph: draws the emoji itself as the row icon.
    local id = api.add_result(title_case(EMOJI_NAMES[i]),
        EMOJI_GROUPS[EMOJI_GROUP[i]] .. " · Enter to copy", "glyph:" .. EMOJI_CHARS[i], "NoReturn")
    if not id then return end
    shown[id] = i
    -- Zenkai already adds Copy Name to every result.
    api.add_action(id, "Copy Emoji", 1, "edit-copy")
    api.add_action(id, "Copy Codepoints", 3, "edit-copy")
end

function on_query(query)
    shown = {}
    local term = query_term(query)
    if not term then return end
    local words = words_of(term)

    if #words == 0 then
        -- Bare prefix: show the first smileys so the picker isn't empty.
        for i = 1, math.min(40, #EMOJI_CHARS) do add(i) end
        return
    end

    local first = words[1]
    local names, search = EMOJI_NAMES, EMOJI_SEARCH
    -- 1 exact name, 2 whole word in the name, 3 name starts with it,
    -- 4 a word in the name starts with it, 5 keyword match.
    local buckets = { {}, {}, {}, {}, {} }
    local found = 0

    if #words == 1 and #first <= 2 then
        -- One or two letters match almost everything, so only take names (or words in
        -- names) that start with them, in table order, and stop at MAX_RESULTS. Keeps the
        -- hook well inside the sandbox's instruction limit.
        local n, spaced = #first, " " .. first
        local starts, words_at = buckets[3], buckets[4]
        for i = 1, #names do
            local name = names[i]
            if sub(name, 1, n) == first then
                starts[#starts + 1] = i
                found = found + 1
                if #starts >= MAX_RESULTS then break end
            elseif #words_at < MAX_RESULTS and find(name, spaced, 1, true) then
                words_at[#words_at + 1] = i
                found = found + 1
            end
        end
    else
        local single, n = #words == 1, #first
        for i = 1, #search do
            local s = search[i]
            local pos = find(s, first, 1, true)
            if pos then
                local ok = true
                for w = 2, #words do
                    if not find(s, words[w], 1, true) then ok = false break end
                end
                if ok then
                    local name_len = #names[i]
                    local rank
                    if pos > name_len then
                        rank = 5
                    else
                        local word_start = pos == 1 or sub(s, pos - 1, pos - 1) == " "
                        local after = sub(s, pos + n, pos + n)
                        local word_end = after == " " or after == "|" or after == "-"
                        if not word_start then rank = 5
                        elseif single and pos == 1 and name_len == n then rank = 1
                        elseif word_end then rank = 2
                        elseif pos == 1 then rank = 3
                        else rank = 4 end
                    end
                    local b = buckets[rank]
                    if #b < MAX_RESULTS then b[#b + 1] = i end
                    found = found + 1
                end
            end
        end
        -- Shorter names first within a bucket: "red heart" before "heart with arrow".
        local by_length = function(a, b) return #names[a] < #names[b] end
        for r = 2, 5 do table.sort(buckets[r], by_length) end
    end

    if found == 0 then
        api.add_result("No emoji found", "Try a name like :fire or a feeling like :love", "dialog-information", "NoReturn")
        return
    end
    local count = 0
    for r = 1, 5 do
        for _, i in ipairs(buckets[r]) do
            if count >= MAX_RESULTS then return end
            add(i)
            count = count + 1
        end
    end
end

function on_open(id)
    local i = shown[id]
    if i then api.copy_text(EMOJI_CHARS[i]) end
end

function on_action(id, action)
    local i = shown[id]
    if not i then return end
    if action == 1 then api.copy_text(EMOJI_CHARS[i])
    elseif action == 2 then api.copy_text(EMOJI_NAMES[i])
    elseif action == 3 then api.copy_text(codepoints(EMOJI_CHARS[i])) end
end

